def is_prime(n: int) -> bool:
    """Check if n is a prime number."""
    if n < 2:
        return False
    if n in (2, 3):
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    # Check for factors from 5 up to sqrt(n) with step 6
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def count_Primes_nums(limit: int) -> int:
    """Return the number of prime numbers less than limit."""
    # The problem says "less than", so we check up to limit - 1
    if limit <= 2:
        return 0

    count = 0
    for num in range(2, limit):
        if is_prime(num):
            count += 1

    return count

# Example test cases
assert count_Primes_nums(5) == 2   # Primes less than 5: 2, 3 -> count = 2
assert count_Primes_nums(0) == 0   # No primes < 0
assert count_Primes_nums(1) == 0   # No primes < 1
assert count_Primes_nums(2) == 0   # Primes less than 2: none (since we start at 2, but "less than" excludes it)
assert count_Primes_nums(3) == 1   # Prime less than 3: only 2 -> count = 1
assert count_Primes_nums(10) == 4  # Primes < 10: 2, 3, 5, 7 -> count = 4

print("All tests passed!")

